<?php
declare(strict_types=1);
require_once __DIR__.'/recovery-audit-support.php';
function proofRules():SoSecurity\Authorization\RolePolicy{return new SoSecurity\Authorization\RolePolicy(['owned.proof.use'=>['type'=>'document','roles'=>['member'],'fields'=>['value']]]);}
function proofIntent():SoSecurity\Operation\Intent{return new SoSecurity\Operation\Intent('owned.proof.use',new SoSecurity\Authorization\Resource('tenant','document','proof-object','1'),['value'=>'Owned proof operation'],['value']);}
function proofTarget(string $id='owned',string $scope='tenant'):SoSecurity\Link\Target{return new SoSecurity\Link\Target('owned.download',new SoSecurity\Authorization\Resource($scope,'document',$id,'1'),'/owned/proof',['id'=>$id],'GET');}
function proofServices(EntryEnvironment $x):array
{
    $protected=$x->boundary->protect($x->store);return [new SoSecurity\Operation\Grants($x->store,$x->sessions,new SoSecurity\Authorization\Authorizer($x->provider,proofRules()),static function():bool{return true;},new SoSecurity\Operation\Policy(120,8,300,2,['totp']),$x->e->clock,$x->boundary),new SoSecurity\Link\Links($protected,$x->e->keys,'owned-proofs',new SoSecurity\Link\Policy('https://proof.example.test'),static function():bool{return true;},$x->e->clock),new SoSecurity\Password\ResetTokens($protected,1800,$x->e->clock)];
}
function proofComponents(array $services):array{return [['service'=>$services[0],'scope'=>'tenant'],['service'=>$services[1],'scope'=>'tenant'],['service'=>$services[2],'scope'=>'']];}
function proofSeed(EntryEnvironment $x,array $services):array
{
    $x->boundary->run('owned.proof.roles',static function()use($x):void{$x->e->pdo->exec("UPDATE account_example SET roles='[\"member\"]' WHERE scope='tenant' AND subject='user'");});$g=$services[0];$token=$x->login()->credential()->token();$c=$x->boundary->run('owned.proof.begin',static function()use($g,$token){return $g->begin('tenant','user',$token,proofIntent());});$token=retirementReauthenticate($x,$token);$grant=$x->boundary->run('owned.proof.confirm',static function()use($g,$token,$c){return $g->confirm('tenant','user',$token,proofIntent(),$c->token());});Check::same(true,$grant instanceof SoSecurity\Operation\Grant);
    $pendingToken=$x->login()->credential()->token();$pending=$x->boundary->run('owned.proof.pending',static function()use($g,$pendingToken){return $g->begin('tenant','user',$pendingToken,proofIntent());});$pendingToken=retirementReauthenticate($x,$pendingToken);
    return $x->boundary->run('owned.proof.material',static function()use($x,$services,$token,$grant,$pending,$pendingToken):array{
        $other=new SoSecurity\Password\ResetTokens(new SoSecurity\Storage\FileStore($x->e->directory.'/factors','proof-foreign',$x->e->clock),1800,$x->e->clock);$csrf=new SoSecurity\Csrf\CsrfTokens($x->store,1800,16,$x->e->clock);$nonce=new SoSecurity\Api\NonceStore($x->store,$x->e->clock);Check::same(true,$nonce->consume('owned-signed-request','OwnedConsumedNonce16',$x->e->clock->time+3600));
        return ['session'=>$token,'grant'=>$grant->token(),'pending'=>$pending->token(),'pending_session'=>$pendingToken,'account'=>$x->provider->find('tenant','user'),'factor'=>$x->factorAdapter->binding('tenant','user'),'links'=>[$services[1]->issue(proofTarget('first'),true)->url(),$services[1]->issue(proofTarget('second'))->url(),$services[1]->issue(proofTarget('outside','foreign'))->url()],'reset'=>[$services[2]->issue('user:old-password-v1'),$services[2]->issue('another-user:old-password-v3')],'other_reset'=>$other->issue('user:old-password-v1'),'csrf'=>$csrf->issue('ordinary-form','browser')];
    });
}
function proofArgs(EntryEnvironment $x,SoSecurity\Account\LocalStateWitness $next,array $services,?callable $persist=null):array{return [$next,$x->source,$x->sources['files'],'sessions-and-factors',$x->store,$x->e->clock,$persist??static function($h)use($x):bool{return witnessPersist($h,$x->e->directory.'/factors');},proofComponents($services)];}
function proofSetup(EntryEnvironment $x,EntryEnvironment $op,SoSecurity\Account\StateRetirementControl $control,?callable $persist=null):array
{
    $services=proofServices($x);$old=proofSeed($x,$services);list($next,$token)=containmentStage($x,$op,$control);$plan=SoSecurity\Account\StateProofRetirement::prepare(...array_merge(proofArgs($x,$next,$services,$persist),['witnessBudget']));return [$services,$old,$next,$plan,$token];
}
function proofApproval(EntryEnvironment $op,SoSecurity\Account\StateRetirementControl $control,SoSecurity\Account\StateProofReview $review,string $token):array
{
    $c=$control->beginProofs($review,'user',$token);Check::same(null,$control->confirmProofs($review,'user',$token,$c->token()));$token=retirementReauthenticate($op,$token);$g=$control->confirmProofs($review,'user',$token,$c->token());Check::same(true,$g instanceof SoSecurity\Operation\Grant);return [$token,$g->token()];
}
/** Actual native readers; only identity/factor authority is frozen to prove the epoch effect causally. */
function proofProbe(EntryEnvironment $x,array $old,bool $retired):void
{
    $dir=privateDirectory();try{
        foreach(glob($x->e->directory.'/factors/*.json') as $file){copy($file,$dir.'/'.basename($file));chmod($dir.'/'.basename($file),0600);}$clock=new TestClock();$clock->time=$x->e->clock->time;$store=new SoSecurity\Storage\FileStore($dir,'entry-sessions',$clock);
        $provider=new class($old['account']) implements SoSecurity\Auth\IdentityProvider{private $a;public function __construct($a){$this->a=$a;}public function authenticate(string $scope,string $id,string $password):?SoSecurity\Auth\Account{return $this->a;}public function find(string $scope,string $subject):?SoSecurity\Auth\Account{return $scope===$this->a->scope()&&$subject===$this->a->subject()?$this->a:null;}};
        $factor=new class($old['factor']) implements SoSecurity\Auth\SecondFactor{private $b;public function __construct(string $b){$this->b=$b;}public function binding(string $scope,string $subject):?string{return $this->b;}public function verify(string $scope,string $subject,string $expected,$proof):?string{throw new RuntimeException('Epoch proof checks must not reauthenticate with a permissive adapter.');}};
        $sessions=new SoSecurity\Auth\SessionRegistry($store,$provider,$factor,$clock,1800,28800,16);$g=new SoSecurity\Operation\Grants($store,$sessions,new SoSecurity\Authorization\Authorizer($provider,proofRules()),static function():bool{return true;},new SoSecurity\Operation\Policy(120,8,300,2,['totp']),$clock);
        Check::same(!$retired,$g->consume('tenant','user',$old['session'],proofIntent(),$old['grant']) instanceof SoSecurity\Operation\Permit);Check::same(!$retired,$g->confirm('tenant','user',$old['pending_session'],proofIntent(),$old['pending']) instanceof SoSecurity\Operation\Grant);
        $links=new SoSecurity\Link\Links($store,$x->e->keys,'owned-proofs',new SoSecurity\Link\Policy('https://proof.example.test'),static function():bool{return true;},$clock);foreach([0,1] as $i){Check::same(!$retired,$links->verify(proofTarget($i===0?'first':'second'),$old['links'][$i]) instanceof SoSecurity\Link\VerifiedLink);}Check::same(true,$links->verify(proofTarget('outside','foreign'),$old['links'][2]) instanceof SoSecurity\Link\VerifiedLink);
        $reset=new SoSecurity\Password\ResetTokens($store,1800,$clock);foreach(['user:old-password-v1','another-user:old-password-v3'] as $i=>$binding){Check::same(!$retired,(new SoSecurity\Csrf\CsrfTokens($store,1800,4,$clock))->verify('password-reset',$binding,$old['reset'][$i]));Check::same(!$retired,$reset->consume($binding,$old['reset'][$i]));}Check::same(true,(new SoSecurity\Password\ResetTokens(new SoSecurity\Storage\FileStore($dir,'proof-foreign',$clock),1800,$clock))->consume('user:old-password-v1',$old['other_reset']));Check::same(true,(new SoSecurity\Csrf\CsrfTokens($store,1800,16,$clock))->verify('ordinary-form','browser',$old['csrf']));Check::same(false,(new SoSecurity\Api\NonceStore($store,$clock))->consume('owned-signed-request','OwnedConsumedNonce16',$clock->time+3600));
        if($retired){$fresh=$links->issue(proofTarget('new-resource'),true);Check::same(true,$links->verify(proofTarget('new-resource'),$fresh->url()) instanceof SoSecurity\Link\VerifiedLink);Check::same(null,$links->verify(proofTarget('new-resource'),$fresh->url()));$freshReset=$reset->issue('user:new-password-v9');Check::same(true,$reset->consume('user:new-password-v9',$freshReset));Check::same(false,$reset->consume('user:new-password-v9',$freshReset));
            $c=$g->begin('tenant','user',$old['session'],proofIntent());$identity=(new SoSecurity\Auth\IdentityState($provider,$factor))->load('tenant','user');$ref=SoSecurity\Auth\SessionRegistry::reference($old['session']);$new=$sessions->replace('tenant','user',$identity['fingerprint'],$sessions->epoch('tenant','user'),'totp',$ref['id'],$ref['digest']);$approved=$g->confirm('tenant','user',$new->token(),proofIntent(),$c->token());Check::same(true,$approved instanceof SoSecurity\Operation\Grant);Check::same(true,$g->consume('tenant','user',$new->token(),proofIntent(),$approved->token()) instanceof SoSecurity\Operation\Permit);Check::same(null,$g->consume('tenant','user',$new->token(),proofIntent(),$approved->token()));
        }
    }finally{cleanDirectory($dir);}
}
function proofAssertions(EntryEnvironment $x,array $old,SoSecurity\Account\LocalStateWitness $next,SoSecurity\Account\StateProofRetirement $plan,array $before,array $done):void
{
    Check::same('quarantined',$done['status']);Check::same('complete',$done['remediation']['phase']);Check::same($before['digest'],$done['digest']);Check::same($plan->manifest(),$done['remediation']['manifest']);foreach($plan->manifest()['entries'] as $e){Check::same($e['after'],file_get_contents($x->e->directory.'/factors/'.$e['reference']['file']));}proofProbe($x,$old,true);$dump=json_encode($done);foreach([$old['session'],$old['grant'],$old['pending'],$old['pending_session'],$old['reset'][0],$old['reset'][1],$old['links'][0],$old['links'][1]] as $secret){Check::same(false,strpos($dump,$secret)!==false);}
}
